"""Bounded SearchApi acquisition; raw JSON is discarded inside each Activity."""
from __future__ import annotations

import asyncio
import hashlib
import json
from datetime import UTC, datetime
from typing import Any
from zoneinfo import ZoneInfo

import httpx
from pydantic import ValidationError

from cpfc_trip.config import Settings
from cpfc_trip.domain import Evidence, Journey, Leg, Offer, Party, Quote, SearchBatch, SearchSpec, Stay
from cpfc_trip.planner.links import flight_url, hotel_url, safe_url
from cpfc_trip.planner.prices import money

ENDPOINT = "https://www.searchapi.io/api/v1/search"


class ProviderError(Exception):
    """A sanitized, user-safe provider failure (never includes credentials or raw URLs)."""


def fingerprint(params: object) -> str:
    return hashlib.sha256(json.dumps(params, sort_keys=True, default=str).encode()).hexdigest()[:24]


class SearchApi:
    def __init__(self, client: httpx.AsyncClient, settings: Settings, limit: int = 5):
        self.client, self.settings, self.limit = client, settings, limit
        self.calls = 0

    async def get(self, params: dict[str, Any]) -> dict[str, Any]:
        if not self.settings.searchapi_enabled or not self.settings.searchapi_api_key.get_secret_value():
            raise ProviderError("Travel search is currently unavailable")
        if self.calls >= self.limit:
            raise ProviderError("Search request limit reached")
        self.calls += 1
        # Temporal owns the single retry of this bounded adapter Activity. HTTP SDK retries are off.
        try:
            response = await self.client.get(
                ENDPOINT, params=params,
                headers={"Authorization": f"Bearer {self.settings.searchapi_api_key.get_secret_value()}"},
                timeout=20,
            )
            response.raise_for_status()
            if len(response.content) > 4_000_000:
                raise ProviderError("Travel search response exceeded its size limit")
            data = response.json()
            if not isinstance(data, dict) or data.get("error") or data.get("errors"):
                raise ProviderError("Travel search returned an error")
            return data
        except (httpx.HTTPError, ValueError) from_none:
            raise ProviderError("Travel search did not return usable results") from None


def evidence(data: dict[str, Any], source: str, checked: datetime) -> Evidence:
    metadata = data.get("search_metadata", {})
    value = metadata.get("request_url", "")
    return Evidence(underlying_source=source, retrieved_at=checked,
                    source_url=safe_url(value) if value else None)


def offer(data: dict[str, Any], source: str, params: object, checked: datetime,
          url: str | None, seller: str | None = None, key: str = "") -> Offer:
    fid = fingerprint(params)
    return Offer(id=f"{fid}-{key}", booking_url=url, seller=seller,
                 evidence=evidence(data, source, checked), search_fingerprint=fid)


def local_time(point: dict[str, Any], timezone: str) -> datetime:
    return datetime.fromisoformat(f"{point['date']}T{point['time']}").replace(tzinfo=ZoneInfo(timezone))


def normalize_flights(data: dict[str, Any], spec: SearchSpec, checked: datetime) -> SearchBatch:
    selected = data.get("selected_flights", [])
    if len(selected) != 2:
        return SearchBatch(gaps=("Complete outbound and return flights were not available.",))
    params = data.get("search_parameters", {})
    if (params.get("outbound_date") != str(spec.outbound_date)
            or params.get("return_date") != str(spec.return_date)):
        return SearchBatch(gaps=("Returned flight dates did not match the requested dates.",))
    url = flight_url(data.get("search_metadata", {}).get("request_url", ""))
    ref = offer(data, "Google Flights", params, checked, url, "Google Flights")
    options = data.get("booking_options", [])
    value = options[0] if options else {}
    amount = money(value.get("price"), params.get("currency", ""))
    matched = (str(params.get("adults")) == str(spec.party.adults)
               and int(params.get("children", 0)) == len(spec.party.child_ages)
               and not any(a < 2 for a in spec.party.child_ages))
    quote = Quote(id=ref.id, amount=amount, scope="round_trip", unit="party",
                  priced_party=spec.party if matched else None, observed_at=checked,
                  caveats=("Rounded planning price; baggage and optional charges may be extra.",)
                  ) if amount else None
    legs: list[tuple[Leg, ...]] = []
    for index, direction in enumerate(selected):
        flights = direction.get("flights", [])
        # Intermediate airport timezones need an airport catalog. Until reviewed, refuse connections.
        if len(flights) != 1:
            return SearchBatch(gaps=("Connecting-flight airport timezones require further evidence.",))
        flight = flights[0]
        dep, arr = flight["departure_airport"], flight["arrival_airport"]
        london = spec.route.origin.split(",")
        if index == 0:
            valid = dep["id"] in london and arr["id"] == spec.route.destination
            dep_tz, arr_tz = "Europe/London", spec.route.destination_timezone
        else:
            valid = dep["id"] == spec.route.destination and arr["id"] in london
            dep_tz, arr_tz = spec.route.destination_timezone, "Europe/London"
        if not valid:
            return SearchBatch(gaps=("Returned airports did not match the catalog route.",))
        legs.append((Leg(id=f"{ref.id}-{index}", mode="flight", origin=dep["id"],
                         destination=arr["id"], departs_at=local_time(dep, dep_tz),
                         arrives_at=local_time(arr, arr_tz), operator=flight["airline"],
                         service_number=flight.get("flight_number", ""), offer=ref, quote=quote,
                         caveats=("Select and confirm this itinerary on Google Flights.",)),))
    return SearchBatch(journeys=(Journey(id=ref.id, route_id=spec.route.id,
                                        outbound=legs[0], inbound=legs[1]),))


async def search_flights(api: SearchApi, spec: SearchSpec) -> SearchBatch:
    if any(a < 2 for a in spec.party.child_ages):
        return SearchBatch(gaps=("Infant flight pricing is not yet supported.",))
    p = dict(engine="google_flights", departure_id=spec.route.origin,
             arrival_id=spec.route.destination, outbound_date=str(spec.outbound_date),
             return_date=str(spec.return_date), flight_type="round_trip", stops="nonstop",
             adults=spec.party.adults, children=len(spec.party.child_ages),
             currency="GBP", gl="GB", hl="en-GB")
    initial = await api.get(p)
    choices = initial.get("best_flights", []) + initial.get("other_flights", [])
    journeys: list[Journey] = []
    for item in choices[:2]:
        if not item.get("departure_token"):
            continue
        returns = await api.get({**p, "departure_token": item["departure_token"]})
        back = returns.get("best_flights", []) + returns.get("other_flights", [])
        if not back:
            back = returns.get("flights", [])
        token = next((x.get("booking_token") for x in back if x.get("booking_token")), None)
        if not token:
            continue
        selected = await api.get({**p, "booking_token": token})
        result = normalize_flights(selected, spec, datetime.now(UTC))
        journeys.extend(result.journeys)
    return SearchBatch(journeys=tuple(journeys), calls=api.calls,
                       gaps=() if journeys else ("No complete flight result was verified.",))


def normalize_stay(prop: dict[str, Any], details: dict[str, Any], search: dict[str, Any],
                   spec: SearchSpec, checked: datetime) -> Stay | None:
    name = prop.get("room_type", "")
    room = next((x for x in details.get("rooms", []) if x.get("name") == name), None)
    if room is None:
        return None
    url = hotel_url(prop.get("link", ""), str(spec.outbound_date), str(spec.return_date), spec.party)
    if not url:
        return None
    ref = offer(search, "Booking.com", spec.model_dump(mode="json"), checked, url,
                "Booking.com", str(prop.get("property_id", "")))
    summary = prop.get("stay_summary", "")
    nights = (spec.return_date - spec.outbound_date).days
    # Only the tested adult/one-room shape establishes group scope. Others remain observations.
    verified = (not spec.party.child_ages and spec.party.rooms == 1
                and summary == f"{nights} nights, {spec.party.adults} adults")
    amount = money(prop.get("extracted_price"), prop.get("currency", ""))
    taxes = money(prop.get("extracted_taxes_and_charges"), prop.get("currency", ""))
    quote = Quote(id=ref.id, amount=amount, scope="stay", unit="party" if verified else "unknown",
                  priced_party=spec.party if verified else None, observed_at=checked,
                  taxes="excluded" if taxes else "unknown", additional_taxes=taxes,
                  caveats=("Search price is rounded. Confirm exact total and cancellation terms.",)
                  ) if amount else None
    return Stay(id=ref.id, property_name=prop["title"], check_in=spec.outbound_date,
                check_out=spec.return_date, room_description=name, offer=ref, quote=quote,
                bathroom="private" if "private bathroom" in name.lower() else
                "shared" if "shared bathroom" in name.lower() else "unknown",
                room_type="dorm" if "dorm" in name.lower() else "private",
                max_guests=room.get("max_guests"), review_score=prop.get("rating"),
                caveats=("Property and room must be reselected on Booking.com.",
                         "Venue access, late check-in and post-match transfers need confirmation."))


async def search_stays(api: SearchApi, spec: SearchSpec) -> SearchBatch:
    p: dict[str, Any] = dict(engine="booking", q=spec.fixture.city,
                            check_in_date=str(spec.outbound_date), check_out_date=str(spec.return_date),
                            adults=spec.party.adults, rooms=spec.party.rooms,
                            currency="GBP", language="en-gb", sort_by="price_low_to_high")
    if spec.party.child_ages:
        # Engine-specific child parameter contract must be proven before quoting children.
        return SearchBatch(gaps=("Accommodation prices for children need a direct occupancy check.",))
    search = await api.get(p)
    stays = []
    for prop in search.get("properties", [])[:3]:
        url = hotel_url(prop.get("link", ""), str(spec.outbound_date), str(spec.return_date), spec.party)
        if not url:
            continue
        details = await api.get({k: v for k, v in {**p, "engine": "booking_property", "url": url}.items()
                                 if k not in {"q", "sort_by"}})
        item = normalize_stay(prop, details, search, spec, datetime.now(UTC))
        if item:
            stays.append(item)
    return SearchBatch(stays=tuple(stays), calls=api.calls,
                       gaps=() if stays else ("No dated room with verified identity was found.",))


def normalize_trains(data: dict[str, Any], origin: str, destination: str, day: str,
                     checked: datetime) -> tuple[Leg, ...]:
    block = data.get("train_results") or {}
    if block.get("date") != day or block.get("origin") != origin or block.get("destination") != destination:
        return ()
    legs = []
    for train in block.get("trains", [])[:8]:
        window = train.get("time_window", {})
        offers = train.get("buy_ticket", {}).get("offers", [])
        selected = next((x for x in offers if safe_url(x.get("link", ""))), None)
        if not selected:
            continue
        try:
            dep = datetime.fromisoformat(window["depart_at_iso"])
            arr = datetime.fromisoformat(window["arrive_at_iso"])
            if dep.date().isoformat() != day or dep.tzinfo is None or arr.tzinfo is None:
                continue
            ref = offer(data, "Google train results", (origin, destination, day, str(dep)),
                        checked, safe_url(selected["link"]), selected.get("source"))
            amount = money(selected.get("extracted_price"), selected.get("currency", ""))
            quote = Quote(id=ref.id, amount=amount, scope="leg", unit="person",
                          priced_party=None, observed_at=checked,
                          caveats=("Single-person indicative fare; party, railcards and payable currency unverified.",)
                          ) if amount else None
            legs.append(Leg(id=ref.id, mode="rail", origin=origin, destination=destination,
                            departs_at=dep, arrives_at=arr, operator=selected.get("source", "Rail"),
                            offer=ref, quote=quote,
                            caveats=(f"{train.get('transfers', 'Unknown')} changes; verify stations and connections.",)))
        except (KeyError, ValueError, ValidationError):
            continue
    return tuple(legs)


async def search_trains(api: SearchApi, spec: SearchSpec) -> SearchBatch:
    if spec.route.onward_stations:
        return SearchBatch(gaps=("Multi-leg rail pattern awaits reviewed station-transfer evidence.",))
    results = []
    for origin, destination, day in [(spec.route.origin, spec.route.destination, spec.outbound_date),
                                     (spec.route.destination, spec.route.origin, spec.return_date)]:
        data = await api.get(dict(engine="google", q=f"trains from {origin} to {destination} on {day:%d %B %Y}",
                                  gl="uk", hl="en"))
        results.append(normalize_trains(data, origin, destination, str(day), datetime.now(UTC)))
    journeys = tuple(Journey(id=f"{a.id}-{b.id}", route_id=spec.route.id, outbound=(a,), inbound=(b,))
                     for a, b in zip(results[0][:2], results[1][:2], strict=False))
    return SearchBatch(journeys=journeys, calls=api.calls,
                       gaps=() if journeys else ("Dated train service evidence is missing.",))


async def acquire(spec: SearchSpec, mode: str) -> SearchBatch:
    if not spec.route.enabled:
        return SearchBatch(gaps=("This catalog pattern has not passed its evidence review.",))
    async with httpx.AsyncClient(follow_redirects=False) as client:
        api = SearchApi(client, Settings())
        try:
            async with asyncio.timeout(100):
                if mode == "stay":
                    return await search_stays(api, spec)
                if mode == "flight":
                    return await search_flights(api, spec)
                return await search_trains(api, spec)
        except (ProviderError, KeyError, ValueError, TimeoutError):
            return SearchBatch(gaps=("Travel evidence is currently incomplete; please check the provider.",),
                               calls=api.calls)
