"""Preserve API keys; add local-only encryption secrets without printing them."""
from pathlib import Path
import secrets
from cryptography.fernet import Fernet

path = Path('.env')
lines = path.read_text().splitlines() if path.exists() else Path('.env.example').read_text().splitlines()
values = dict(line.split('=', 1) for line in lines if '=' in line and not line.startswith('#'))
for key, value in {'CONTACT_ENCRYPTION_KEY': Fernet.generate_key().decode(),
                   'SESSION_SECRET': secrets.token_urlsafe(48)}.items():
    if not values.get(key):
        lines = [line for line in lines if not line.startswith(key + '=')]
        lines.append(key + '=' + value)
# Old mock/console modes have been replaced with explicitly labeled sample/preview modes.
lines = [line.replace('PLANNER_MODE=mock', 'PLANNER_MODE=recorded').replace('EMAIL_MODE=console', 'EMAIL_MODE=preview') for line in lines]
path.write_text('\n'.join(lines) + '\n')
path.chmod(0o600)
print('Local configuration prepared; existing provider keys preserved.')
